CREATE FUNCTION public.can_access_document(p_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM public.tenants t JOIN public.tenant_memberships m ON m.tenant_id=t.id WHERE t.slug=(storage.foldername(p_name))[1] AND m.user_id=auth.uid() AND (m.role='HQ' OR m.store_id::text=(storage.foldername(p_name))[2])); $$; REVOKE ALL ON FUNCTION public.can_access_document(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_access_document(text) TO authenticated; DROP POLICY tenant_documents ON storage.objects; CREATE POLICY tenant_documents ON storage.objects FOR ALL TO authenticated USING(bucket_id='employee-docs' AND public.can_access_document(name)) WITH CHECK(bucket_id='employee-docs' AND public.can_access_document(name));
